INSERT INTO feature VALUES('modular-implicits','checking','Modular implicits: a model resolved for an implicit','implicit-arguments','implemented','notable',NULL,'A function quantifies over a model in its prefix block, `[s : Model(S)]`, which binds one implicit parameter per component of `S` (a sort a manifest model type fixes binds none) and no record of the model; the body reads each as `s.x`. A call supplies a module by its name, `f[.s = M]`, passing its members, a module of a theory including `S` passing its reduct, or passes a model implicit of its own on, `f[.s = t]`; a model implicit named alone or supplied a value is refused; a call omitting the slot resolves it to the one module in scope, local or imported, whose ascription is `Model(S)` or a model of a theory including `S`, at the types its explicit arguments force and, at a manifest model type, at the sorts the type fixes, counting modules whose components convert, as a module including another does at that model, as one elaboration, and refuses a slot no module answers or two elaborations do, naming every module left. Path endpoints compared while a slot they call through is unresolved, `Path.here(x == y)` at `Path[.A = Bool](x == y, x == y)` among them, wait for the resolution, and are judged with the body and the declared type both filled. A slot the declared type alone decides resolves before the body, so a declared type that decodes a comparison, `decoded(ofFlag(x == y))`, runs it; a slot the declared type leaves undecided waits for the body. A declared type that decodes through such a slot is refused as the slot''s resolution refuses it, `ModelAmbiguous` or `ModelUnanswered`. The printer and the hover write it as the source does: a definition''s slot whole with its fixed sorts, each component by its path, and a call''s supply by the module or the implicit it names.','surface-lowering core-checker surface-pretty surface-diagnostics surface-dispatcher','corpus/model/modules/model-implicit.gandr corpus/model/modules/model-implicit-manifest.gandr corpus/model/modules/model-resolution.gandr corpus/model/modules/model-resolution-swapped.gandr corpus/model/modules/model-resolution-manifest.gandr corpus/model/modules/model-include.gandr corpus/model/identity/here-congruence.gandr corpus/model/modules/model-stated-type.gandr corpus/model/basics/literal-identity.gandr corpus/pathological/modules/model-implicit-supply.gandr corpus/pathological/modules/model-implicit-resolution.gandr corpus/pathological/modules/model-include.gandr corpus/pathological/modules/model-stated-type.gandr','corpus/model/modules/model-implicit.gandr',NULL);
